INSERT INTO states (name, slug, tagline, description, best_season, peak_season, highlights, color) VALUES
('Andhra Pradesh', 'andhra-pradesh', 'Land of Temples and Coastlines', 'A southeastern state of ancient Buddhist sites, Tirupati pilgrimage, and a long Bay of Bengal coastline with growing port cities.', 'Winter (Nov-Feb)', 'January', '["Tirupati Balaji Temple", "Araku Valley", "Amaravati Stupa", "Vizag Beaches", "Lepakshi Temple"]', '#0ea5e9'),
('Arunachal Pradesh', 'arunachal-pradesh', 'Land of the Dawn-Lit Mountains', 'India''s easternmost frontier of Himalayan monasteries, alpine passes, and tribal cultures, crowned by Tawang Monastery.', 'Spring (Mar-May)', 'April', '["Tawang Monastery", "Sela Pass", "Ziro Valley", "Namdapha Forests", "Dirang Valley"]', '#0d9488'),
('Assam', 'assam', 'Gateway to the Northeast', 'A Brahmaputra valley state of one-horned rhinos at Kaziranga, tea gardens, the Kamakhya Shakti shrine, and Ahom heritage.', 'Winter (Nov-Mar)', 'February', '["Kaziranga Rhinos", "Kamakhya Temple", "Majuli Island", "Tea Gardens", "Manas National Park"]', '#65a30d'),
('Bihar', 'bihar', 'Cradle of Empires and Enlightenment', 'An ancient land of Nalanda''s university ruins, the Mahabodhi Temple where Buddha attained enlightenment, and Mauryan history.', 'Winter (Oct-Mar)', 'November', '["Mahabodhi Temple", "Nalanda Ruins", "Golghar Patna", "Vikramshila", "Rajgir Hot Springs"]', '#b45309'),
('Chhattisgarh', 'chhattisgarh', 'Land of Waterfalls and Tribes', 'A central Indian state of dense forests, Bastar tribal culture, and Chitrakote — the Niagara of India.', 'Winter (Oct-Mar)', 'December', '["Chitrakote Falls", "Bastar Tribal Culture", "Bhoramdeo Temple", "Kanger Valley", "Sirpur Heritage"]', '#15803d'),
('Gujarat', 'gujarat', 'Land of Legends and Lions', 'A western state of Asiatic lions at Gir, the white Rann of Kutch, Somnath Jyotirlinga, and Mahatma Gandhi''s Sabarmati Ashram.', 'Winter (Nov-Feb)', 'December', '["Rann of Kutch", "Gir Lions", "Somnath Temple", "Sabarmati Ashram", "Statue of Unity"]', '#db2777'),
('Haryana', 'haryana', 'Land of Kurukshetra', 'A northern plains state around Delhi of Mahabharata heritage at Kurukshetra, Surajkund crafts, and modern Gurugram.', 'Winter (Oct-Mar)', 'November', '["Brahma Sarovar", "Surajkund Mela", "Sultanpur Bird Sanctuary", "Kingdom of Dreams", "Pinjore Gardens"]', '#7c3aed'),
('Jharkhand', 'jharkhand', 'Land of Forests and Falls', 'A mineral-rich eastern state of waterfalls around Ranchi, the Baidyanath Jyotirlinga at Deoghar, and tribal culture.', 'Winter (Oct-Mar)', 'December', '["Hundru Falls", "Baidyanath Temple", "Betla National Park", "Dassam Falls", "Parasnath Hill"]', '#047857'),
('Karnataka', 'karnataka', 'Land of Heritage and Hills', 'A southern state of Hampi''s Vijayanagara ruins, Mysuru Palace, Coorg coffee hills, and Bengaluru''s tech buzz.', 'Winter (Oct-Feb)', 'December', '["Hampi Ruins", "Mysuru Palace", "Coorg Hills", "Jog Falls", "Gokarna Beaches"]', '#9333ea'),
('Madhya Pradesh', 'madhya-pradesh', 'Heart of Incredible India', 'India''s central state of Khajuraho temples, Sanchi Stupa, tiger reserves, and the holy city of Ujjain.', 'Winter (Oct-Mar)', 'November', '["Khajuraho Temples", "Sanchi Stupa", "Bandhavgarh Tigers", "Mahakaleshwar Ujjain", "Bhimbetka Caves"]', '#c2410c'),
('Maharashtra', 'maharashtra', 'Gateway to the Heart of India', 'A western powerhouse of Mumbai''s Gateway, Ellora and Ajanta cave temples, hill forts, and Konkan beaches.', 'Winter (Nov-Feb)', 'December', '["Gateway of India", "Ellora Caves", "Shaniwar Wada", "Lonavala Hills", "Tadoba Tigers"]', '#e11d48'),
('Manipur', 'manipur', 'Jewel of India', 'A northeastern valley state of Loktak floating lake, Kangla heritage, polo origins, and vibrant markets run by women.', 'Spring (Feb-May)', 'March', '["Loktak Lake", "Kangla Palace", "Ima Keithel Market", "Keibul Lamjao", "Shirui Hills"]', '#059669'),
('Meghalaya', 'meghalaya', 'Abode of the Clouds', 'A hill state of living root bridges, Asia''s cleanest village Mawlynnong, dramatic waterfalls, and cave systems.', 'Autumn (Sep-Nov)', 'October', '["Living Root Bridges", "Nohkalikai Falls", "Mawlynnong Village", "Dawki River", "Mawsmai Caves"]', '#0891b2'),
('Mizoram', 'mizoram', 'Land of the Highlanders', 'A northeastern hill state of ridgeline towns, bamboo forests, and serene Aizawl valley culture.', 'Winter (Nov-Feb)', 'December', '["Durtlang Hills", "Reiek Peak", "Vantawng Falls", "Murlen Park", "Solomon''s Temple"]', '#4d7c0f'),
('Nagaland', 'nagaland', 'Land of Festivals', 'A hill state of Naga tribes, the Hornbill Festival at Kisama, and the historic Kohima War Cemetery.', 'Winter (Oct-Dec)', 'December', '["Hornbill Festival", "Kohima War Cemetery", "Dzukou Valley", "Kisama Village", "Japfu Peak"]', '#6d28d9'),
('Odisha', 'odisha', 'Soul of Incredible India', 'An eastern coastal state of the Jagannath Temple, Konark Sun Temple, Chilika lagoon, and classical Odissi dance.', 'Winter (Oct-Feb)', 'December', '["Jagannath Temple", "Konark Sun Temple", "Chilika Lake", "Puri Beach", "Lingaraj Temple"]', '#0e7490'),
('Punjab', 'punjab', 'Land of Five Rivers', 'A northwestern state of the Golden Temple at Amritsar, Sikh heritage, mustard fields, and legendary hospitality.', 'Winter (Oct-Mar)', 'November', '["Golden Temple", "Wagah Border Ceremony", "Jallianwala Bagh", "Qila Mubarak", "Anandpur Sahib"]', '#ca8a04'),
('Sikkim', 'sikkim', 'Himalayan Paradise', 'A Himalayan state of monasteries, Kanchenjunga views, Yumthang flowers, and India''s first organic state.', 'Spring (Mar-May)', 'April', '["Rumtek Monastery", "Yumthang Valley", "Gurudongmar Lake", "MG Marg Gangtok", "Nathula Pass"]', '#2563eb'),
('Telangana', 'telangana', 'Land of Charminar', 'India''s youngest state of Hyderabad''s Charminar and Golconda, Warangal Kakatiya temples, and Deccan cuisine.', 'Winter (Nov-Feb)', 'December', '["Charminar", "Golconda Fort", "Thousand Pillar Temple", "Ramoji Film City", "Nagarjuna Sagar"]', '#be123c'),
('Tripura', 'tripura', 'Land of Palaces and Temples', 'A northeastern state of Ujjayanta Palace, Tripura Sundari Shakti shrine, and bamboo craft traditions.', 'Winter (Oct-Mar)', 'November', '["Ujjayanta Palace", "Tripura Sundari Temple", "Neermahal Palace", "Unakoti Rock Carvings", "Sepahijala Wildlife"]', '#a16207'),
('Uttar Pradesh', 'uttar-pradesh', 'Heartland of Heritage', 'India''s most populous state of the Taj Mahal, Varanasi ghats, Lucknow tehzeeb, and Mathura-Vrindavan devotion.', 'Winter (Oct-Mar)', 'November', '["Taj Mahal", "Varanasi Ghats", "Bara Imambara", "Sarnath", "Fatehpur Sikri"]', '#9a3412'),
('Uttarakhand', 'uttarakhand', 'Land of the Gods', 'A Himalayan state of Char Dham pilgrimage, Rishikesh yoga, Nainital lakes, and Valley of Flowers treks.', 'Summer (Mar-Jun)', 'May', '["Kedarnath Temple", "Naini Lake", "Rishikesh Yoga", "Valley of Flowers", "Har Ki Dun Trek"]', '#1d4ed8'),
('West Bengal', 'west-bengal', 'City of Joy and Beyond', 'An eastern state of Kolkata''s colonial grandeur, Darjeeling tea and toy train, and Sundarbans mangroves.', 'Winter (Oct-Mar)', 'December', '["Victoria Memorial", "Darjeeling Toy Train", "Howrah Bridge", "Sundarbans", "Dakshineswar Temple"]', '#b91c1c'),
('Andaman and Nicobar Islands', 'andaman-and-nicobar-islands', 'Emerald Islands', 'A Bay of Bengal archipelago of Cellular Jail history, Radhanagar Beach, and world-class diving reefs.', 'Winter (Nov-Apr)', 'December', '["Cellular Jail", "Radhanagar Beach", "Scuba Diving", "Ross Island", "Limestone Caves"]', '#155e75'),
('Chandigarh', 'chandigarh', 'The City Beautiful', 'India''s first planned city by Le Corbusier, of the Rock Garden, Sukhna Lake, and grid-sector modernism.', 'Spring (Feb-Apr)', 'March', '["Rock Garden", "Sukhna Lake", "Rose Garden", "Capitol Complex", "Sector 17 Plaza"]', '#4f46e5'),
('Dadra and Nagar Haveli and Daman and Diu', 'dnh-and-dd', 'Portuguese Heritage Coast', 'A union territory of Daman''s Portuguese forts and beaches plus the green tribal belt of Dadra and Nagar Haveli.', 'Winter (Nov-Mar)', 'December', '["Moti Daman Fort", "Jampore Beach", "Dudhni Lake", "Nani Daman Church", "Vasona Lion Safari"]', '#14b8a6'),
('Delhi', 'delhi', 'The Eternal Capital', 'India''s capital territory of Mughal grandeur at Red Fort and Humayun''s Tomb, India Gate, and Old Delhi''s bazaars.', 'Winter (Oct-Mar)', 'November', '["India Gate", "Red Fort", "Qutub Minar", "Humayun''s Tomb", "Chandni Chowk"]', '#dc2626'),
('Jammu and Kashmir', 'jammu-and-kashmir', 'Paradise on Earth', 'A northern UT of Dal Lake houseboats, Vaishno Devi pilgrimage, Pahalgam valleys, and saffron fields.', 'Summer (Apr-Oct)', 'June', '["Dal Lake", "Vaishno Devi", "Pahalgam Valley", "Gulmarg Skiing", "Shalimar Bagh"]', '#1e40af'),
('Ladakh', 'ladakh', 'Land of High Passes', 'A trans-Himalayan desert of Pangong Lake, ancient monasteries, Khardung La, and stark moon-like landscapes.', 'Summer (May-Sep)', 'July', '["Pangong Lake", "Thiksey Monastery", "Khardung La", "Nubra Sand Dunes", "Shanti Stupa"]', '#0369a1'),
('Lakshadweep', 'lakshadweep', 'Coral Paradise', 'An Arabian Sea archipelago of coral atolls, lagoons, and untouched beaches off the Kerala coast.', 'Winter (Oct-Mar)', 'December', '["Agatti Beach", "Minicoy Island", "Scuba Lagoons", "Kalpeni Atoll", "Bangaram Island"]', '#0284c7'),
('Puducherry', 'puducherry', 'French Riviera of the East', 'A former French colony of mustard-yellow streets, Rock Beach promenade, Aurobindo Ashram, and Auroville.', 'Winter (Nov-Feb)', 'December', '["Rock Beach", "French Quarter", "Auroville", "Aurobindo Ashram", "Paradise Beach"]', '#f59e0b');
