INSERT INTO tourist_spots (district_id, name, description, category, latitude, longitude, rating, entry_fee, visit_duration) VALUES
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Visakhapatnam' AND s.name='Andhra Pradesh'), 'RK Beach Vizag', 'A lively city beach along Beach Road, popular for sunrise walks and submarine museum visits nearby.', 'Beach', 17.714500, 83.315700, 4.3, 'Free', '2-3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Visakhapatnam' AND s.name='Andhra Pradesh'), 'Kailasagiri Hill', 'A hilltop park with panoramic bay views, ropeway rides, and giant Shiva-Parvati statues.', 'Viewpoint', 17.749200, 83.341500, 4.4, 'Rs. 50', '2-3 hours'),
