((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Kolkata' AND s.name='West Bengal'), 'Howrah Bridge', 'The 1943 cantilever icon over the Hooghly, among the world''s busiest bridges.', 'Bridge', 22.585000, 88.346000, 4.6, 'Free', '1 hour'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Kolkata' AND s.name='West Bengal'), 'Dakshineswar Temple', 'Ramakrishna''s Kali temple on the Hooghly with twelve Shiva shrines.', 'Temple', 22.655000, 88.357000, 4.8, 'Free', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Darjeeling' AND s.name='West Bengal'), 'Tiger Hill Sunrise', 'The classic Kanchenjunga and Everest sunrise viewpoint above Darjeeling.', 'Viewpoint', 27.000000, 88.280000, 4.7, 'Rs. 50', 'Half day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Darjeeling' AND s.name='West Bengal'), 'Batasia Loop Railway', 'The spiral toy-train loop with a Gorkha memorial and mountain panorama.', 'Heritage', 27.020000, 88.250000, 4.5, 'Rs. 30', '1-2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='South Andaman' AND s.name='Andaman and Nicobar Islands'), 'Cellular Jail', 'The colonial prison-memorial of freedom fighters with an evening sound show.', 'Memorial', 11.675000, 92.749000, 4.8, 'Rs. 30', '2-3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='South Andaman' AND s.name='Andaman and Nicobar Islands'), 'Radhanagar Beach', 'A Blue-Flag beach on Havelock with powder sand and sunset points.', 'Beach', 11.976000, 92.953000, 4.9, 'Free', 'Half day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Chandigarh' AND s.name='Chandigarh'), 'Rock Garden', 'Nek Chand''s folk-art garden built from urban waste and boulders.', 'Garden', 30.752500, 76.810100, 4.6, 'Rs. 30', '2-3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Chandigarh' AND s.name='Chandigarh'), 'Sukhna Lake', 'A Shivalik-foothill reservoir for rowing, jogging, and sunsets.', 'Lake', 30.743000, 76.820000, 4.5, 'Free', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Daman' AND s.name='Dadra and Nagar Haveli and Daman and Diu'), 'Moti Daman Fort', 'A 16th-century Portuguese fort with lighthouse views over the sea.', 'Heritage', 20.417000, 72.832000, 4.1, 'Free', '1-2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Daman' AND s.name='Dadra and Nagar Haveli and Daman and Diu'), 'Jampore Beach', 'A calm black-sand beach for swimming and water sports near Nani Daman.', 'Beach', 20.400000, 72.830000, 4.2, 'Free', '2-3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Dadra and Nagar Haveli' AND s.name='Dadra and Nagar Haveli and Daman and Diu'), 'Dudhni Lake', 'A reservoir lake ringed by hills, popular for camping and water sports.', 'Lake', 20.280000, 73.050000, 4.2, 'Free', '3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Delhi' AND s.name='Delhi'), 'India Gate', 'The 42m war memorial arch on Kartavya Path, floodlit at night.', 'Monument', 28.612900, 77.229500, 4.8, 'Free', '1-2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Delhi' AND s.name='Delhi'), 'Qutub Minar', 'The 73m victory tower amid Indo-Islamic ruins, a UNESCO site.', 'Heritage', 28.524500, 77.185500, 4.7, 'Rs. 40', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Delhi' AND s.name='Delhi'), 'Red Fort', 'Shah Jahan''s 17th-century walled palace of the Mughal emperors.', 'Heritage', 28.656200, 77.241000, 4.6, 'Rs. 50', '3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Delhi' AND s.name='Delhi'), 'Humayun''s Tomb', 'The garden-tomb prototype of the Taj, a UNESCO Mughal masterpiece.', 'Heritage', 28.593100, 77.250700, 4.7, 'Rs. 40', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Srinagar' AND s.name='Jammu and Kashmir'), 'Dal Lake', 'The Himalayan urban lake of houseboats, shikaras, and floating markets.', 'Lake', 34.100000, 74.870000, 4.8, 'Free', 'Half day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Srinagar' AND s.name='Jammu and Kashmir'), 'Shalimar Bagh', 'Jahangir''s terraced Mughal garden of fountains and chinar trees.', 'Garden', 34.149200, 74.873300, 4.5, 'Rs. 30', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Jammu' AND s.name='Jammu and Kashmir'), 'Vaishno Devi Shrine', 'The Trikuta cave shrine of Mata Vaishno Devi, among India''s busiest pilgrimages.', 'Temple', 33.030800, 74.949400, 4.9, 'Free', 'Full day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Anantnag' AND s.name='Jammu and Kashmir'), 'Pahalgam Valley', 'A Lidder-valley meadow town, base for Amarnath and Betaab Valley trips.', 'Valley', 34.010000, 75.320000, 4.8, 'Free', 'Full day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Leh' AND s.name='Ladakh'), 'Pangong Lake', 'The high-altitude blue lake shifting shades across the Changthang plateau.', 'Lake', 33.850000, 78.670000, 4.9, 'Rs. 20', 'Full day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Leh' AND s.name='Ladakh'), 'Shanti Stupa', 'A white hilltop peace pagoda with Leh town and Stok range views.', 'Monument', 34.170000, 77.570000, 4.7, 'Free', '1-2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Leh' AND s.name='Ladakh'), 'Leh Palace', 'A 17th-century nine-storey royal palace overlooking old Leh town.', 'Heritage', 34.168000, 77.585000, 4.4, 'Rs. 30', '1-2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Kargil' AND s.name='Ladakh'), 'Kargil War Memorial Drass', 'The 1999 war memorial at Drass, second-coldest inhabited place on Earth.', 'Memorial', 34.430000, 75.750000, 4.8, 'Free', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Lakshadweep' AND s.name='Lakshadweep'), 'Agatti Island Beach', 'A coral-island beach with lagoon kayaking and diving off Agatti.', 'Beach', 10.850000, 72.190000, 4.7, 'Free', 'Full day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Lakshadweep' AND s.name='Lakshadweep'), 'Minicoy Island', 'A crescent island of tuna culture, lighthouse, and coral reefs.', 'Island', 8.280000, 73.050000, 4.6, 'Free', 'Full day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Puducherry' AND s.name='Puducherry'), 'Rock Beach Promenade', 'The Bay-side boulevard for sunrise walks past the Gandhi statue.', 'Waterfront', 11.936000, 79.835000, 4.6, 'Free', '1-2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Puducherry' AND s.name='Puducherry'), 'Sri Aurobindo Ashram', 'The spiritual community founded by Sri Aurobindo and the Mother.', 'Spiritual', 11.937000, 79.834000, 4.7, 'Free', '1-2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Puducherry' AND s.name='Puducherry'), 'Auroville Matrimandir', 'The golden meditation globe of the experimental universal township.', 'Spiritual', 11.992000, 79.812000, 4.7, 'Free', 'Half day');
